import asyncio


async def first_reply(servers, timeout):
    async def named(name, call):
        return name, await call()

    tasks = [asyncio.create_task(named(name, call)) for name, call in servers.items()]
    if not tasks:
        return None
    try:
        done, pending = await asyncio.wait(tasks, timeout=timeout, return_when=asyncio.FIRST_COMPLETED)
        if not done:
            return None
        return next(iter(done)).result()
    finally:
        for task in tasks:
            task.cancel()
        await asyncio.gather(*tasks, return_exceptions=True)
